const input = $json || {};
const body = input.body || input;
const headers = input.headers || {};

function header(name) {
  const key = Object.keys(headers).find((item) => item.toLowerCase() === name.toLowerCase());
  return key ? String(headers[key] || "") : "";
}

function firstValue(...values) {
  for (const value of values) {
    if (value !== undefined && value !== null && String(value).trim() !== "") return String(value).trim();
  }
  return "";
}

const expectedToken = $env.ONBOARDING_API_TOKEN;
const providedToken = header("x-onboarding-token");

const userId = firstValue(body.user_id, body.userId);
const organizationId = firstValue(body.organization_id, body.organizationId);
const agentId = firstValue(body.agent_id, body.agentId);
const channelInput = body.channel && typeof body.channel === "object" ? body.channel : {};

const channel = firstValue(channelInput.channel);
const provider = firstValue(channelInput.provider);
const externalChannelId = firstValue(channelInput.external_channel_id, channelInput.externalChannelId);
const displayName = firstValue(channelInput.display_name, channelInput.displayName);
const wabaId = firstValue(
  channelInput.whatsapp_business_account_id,
  channelInput.waba_id,
  channelInput.wabaId
);

let error = null;
if (!expectedToken) error = "missing_onboarding_token_config";
else if (!providedToken || providedToken !== expectedToken) error = "invalid_onboarding_token";
else if (!userId) error = "missing_user_id";
else if (!organizationId) error = "missing_organization_id";
else if (!agentId) error = "missing_agent_id";
else if (!channel) error = "missing_channel";
else if (!provider) error = "missing_provider";
else if (!externalChannelId) error = "missing_external_channel_id";

// Config JSON estandar para el runtime omnicanal (ver agent_channels.config en
// docs/OMNICHANNEL_IMPLEMENTATION_GUIDE_2026-06-15.md). whatsapp_business_account_id
// (WABA id) es distinto del phone_number_id -- Meta necesita el WABA id para el paso
// de suscribir la app al webhook de esa cuenta (POST /{waba_id}/subscribed_apps),
// que es independiente de vincular el numero puntual. Se guarda ademas del
// phone_number_id porque una misma WABA puede tener varios numeros, y ese paso de
// suscripcion solo hace falta una vez por WABA, no por numero.
const config = {
  environment: "production",
  inbound_enabled: true,
  outbound_enabled: true,
  display_name: displayName || "",
  default_language: "es-CL",
  provider_credentials_ref: "",
  whatsapp_business_account_id: wabaId || "",
  rate_limit: { messages_per_minute: 60 },
  fallback_policy: { on_error: "handoff_or_retry" }
};

return [{
  json: {
    valid: !error,
    error,
    user_id: userId || null,
    organization_id: organizationId || null,
    agent_id: agentId || null,
    channel: channel || null,
    provider: provider || null,
    external_channel_id: externalChannelId || null,
    display_name: displayName || null,
    whatsapp_business_account_id: wabaId || null,
    config
  }
}];

const input = $json || {};

function sqlText(value) {
  if (value === undefined || value === null || value === "") return "NULL";
  return "'" + String(value).replace(/'/g, "''") + "'";
}

function sqlUuidOrNull(value) {
  const text = String(value || "").trim();
  const isUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(text);
  return isUuid ? "'" + text + "'" : "NULL";
}

function sqlJsonb(value) {
  const json = JSON.stringify(value === undefined ? null : value);
  return "'" + json.replace(/'/g, "''") + "'::jsonb";
}

if (!input.valid) {
  return [{ json: { ...input, channel_query: null } }];
}

const query = `
WITH membership AS (
  SELECT EXISTS (
    SELECT 1 FROM organization_members
    WHERE user_id = ${sqlUuidOrNull(input.user_id)}
      AND organization_id = ${sqlUuidOrNull(input.organization_id)}
  ) AS is_member
),
agent_check AS (
  SELECT EXISTS (
    SELECT 1 FROM agents
    WHERE id = ${sqlUuidOrNull(input.agent_id)}
      AND organization_id = ${sqlUuidOrNull(input.organization_id)}
  ) AS agent_belongs
),
upserted_channel AS (
  INSERT INTO agent_channels (organization_id, agent_id, channel, provider, external_channel_id, display_name, is_active, config)
  SELECT
    ${sqlUuidOrNull(input.organization_id)},
    ${sqlUuidOrNull(input.agent_id)},
    ${sqlText(input.channel)},
    ${sqlText(input.provider)},
    ${sqlText(input.external_channel_id)},
    ${sqlText(input.display_name)},
    true,
    ${sqlJsonb(input.config)}
  WHERE (SELECT is_member FROM membership) AND (SELECT agent_belongs FROM agent_check)
  ON CONFLICT (provider, external_channel_id) DO UPDATE SET
    organization_id = excluded.organization_id,
    agent_id = excluded.agent_id,
    channel = excluded.channel,
    display_name = excluded.display_name,
    is_active = true,
    config = excluded.config,
    updated_at = now()
  RETURNING id, agent_id
)
SELECT
  (SELECT is_member FROM membership) AS is_member,
  (SELECT agent_belongs FROM agent_check) AS agent_belongs,
  (SELECT id FROM upserted_channel) AS channel_id
;
`;

return [{
  json: {
    ...input,
    channel_query: query
  }
}];

const upstream = $("build_channel_query").first().json;
const dbResult = $json || {};

const isMember = dbResult.is_member === true || dbResult.is_member === "t" || dbResult.is_member === "true";
const agentBelongs = dbResult.agent_belongs === true || dbResult.agent_belongs === "t" || dbResult.agent_belongs === "true";
const channelId = dbResult.channel_id || null;

let status = "ok";
if (!isMember) status = "forbidden";
else if (!agentBelongs) status = "agent_not_found";
else if (!channelId) status = "creation_failed";

return [{
  json: {
    status,
    channel_id: channelId,
    agent_id: upstream.agent_id,
    organization_id: upstream.organization_id,
    channel: upstream.channel,
    provider: upstream.provider,
    external_channel_id: upstream.external_channel_id,
    whatsapp_business_account_id: upstream.whatsapp_business_account_id
  }
}];

const input = $json || {};

if (input.status === "forbidden") {
  return [{ json: { ok: false, error: "forbidden", message: "El usuario no pertenece a esa organizacion.", channel_id: null } }];
}
if (input.status === "agent_not_found") {
  return [{ json: { ok: false, error: "agent_not_found", message: "El agente no existe o no pertenece a esa organizacion.", channel_id: null } }];
}
if (input.status === "creation_failed") {
  return [{ json: { ok: false, error: "creation_failed", message: "No se pudo vincular el canal. Revisa external_channel_id o intenta de nuevo.", channel_id: null } }];
}

return [{
  json: {
    ok: true,
    channel_id: input.channel_id,
